import React, { useState, useEffect } from 'react';

export default function ThemeToggle() {
  const [themeMode, setThemeMode] = useState(() => {
    return localStorage.getItem('user_theme') || 'system';
  });

  useEffect(() => {
    const root = window.document.documentElement;
    const isDarkSystem = window.matchMedia('(prefers-color-scheme: dark)').matches;

    // Xóa lớp cũ trước khi áp dụng
    root.classList.remove('light', 'dark');

    if (themeMode === 'dark' || (themeMode === 'system' && isDarkSystem)) {
      root.classList.add('dark');
      root.style.backgroundColor = '#0f172a'; // Màu slate-900 cho chế độ tối
    } else {
      root.classList.add('light');
      root.style.backgroundColor = '#f8fafc'; // Màu gray-50 cho chế độ sáng
    }

    localStorage.setItem('user_theme', themeMode);
  }, [themeMode]);

  return (
    <div className="inline-flex items-center bg-slate-800 p-1 rounded-xl border border-slate-700 text-xs font-medium">
      <button
        onClick={() => setThemeMode('light')}
        className={`px-2.5 py-1.5 rounded-lg transition-all ${themeMode === 'light' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-300 hover:text-white'}`}
      >
        ☀️ Sáng
      </button>
      <button
        onClick={() => setThemeMode('dark')}
        className={`px-2.5 py-1.5 rounded-lg transition-all ${themeMode === 'dark' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-300 hover:text-white'}`}
      >
        🌙 Tối
      </button>
      <button
        onClick={() => setThemeMode('system')}
        className={`px-2.5 py-1.5 rounded-lg transition-all ${themeMode === 'system' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-300 hover:text-white'}`}
      >
        💻 Hệ thống
      </button>
    </div>
  );
}
